/** Immutable evidence and report inputs. Report rendering never rejoins mutable
 * live accounting, payment, configuration, staff or tax tables. */
final class FinancialSnapshots {
    public function __construct(private PDO $db,private array $user){}
    private static function allowedConfig(string $key,array $v):array {
        $keys=match($key){
            'SCHOOL_IMPLEMENTATION_CLASS'=>['classification','supersedes_version_id'],
            'ORG_OFFICE_HEAD_V1'=>['employee_id'],
            'DV_SECTION_SIGNATORIES_V1'=>['part_a','part_c','part_d'],
            'SCHOOL_DIVISION_MOOE_POSTING_OFFICER_V1'=>['division_id','employee_id','full_name','name','designation','position_title'],
            default=>[]};
        if($key==='travel_activity_request_signatories'){$out=[];foreach(['sgod_chief','sds'] as $role){$id=$v['roles'][$role]['employee_id']??null;if(is_int($id)&&$id>0)$out['roles'][$role]=['employee_id'=>$id];}return $out;}
        $out=[];foreach($keys as $field){if(!array_key_exists($field,$v))continue;$value=$v[$field];
            if(in_array($field,['employee_id','division_id','supersedes_version_id','part_a','part_c','part_d'],true)){if($value===null||is_int($value)&&$value>0)$out[$field]=$value;}
            elseif($field==='classification'){if(in_array($value,['IUS','NON_IUS'],true))$out[$field]=$value;}
            elseif(is_string($value)&&strlen($value)<=500&&!preg_match('/[\x00-\x1F\x7F]/',$value))$out[$field]=$value;
        }return $out;
    }
    /** Inputs with missing or later recorded timestamps are not contemporaneous evidence.
     * The amounts remain visible for reconstructed workpapers, never as a genuine close. */
    public static function lateEvidenceGaps(array $credits,array $sources,string $boundary):array {
        $gaps=[];
        foreach($credits as $row){$stamp=$row['created_at']??null;if(!is_string($stamp)||$stamp===''||$stamp>=$boundary){$gaps[]='A bank credit was recorded after the accounting cutoff or lacks a recorded timestamp; historical credit evidence is reconstructed.';break;}}
        foreach($sources as $row){$stamp=$row['created_at']??null;if(!is_string($stamp)||$stamp===''||$stamp>=$boundary){$gaps[]='A bank reconciliation source was verified after the accounting cutoff or lacks a recorded timestamp; historical source evidence is reconstructed.';break;}}
        return $gaps;
    }
    /** Appointments are versioned, but employee legal names/positions and office
     * or bank directory labels are mutable. A delayed close must not present a
     * later audited identity correction as the identity observed at cutoff.
     * Read only the effective report roles and the matching scoped audit IDs;
     * unrelated staff and payment-profile changes are not report evidence. */
    private static function reportIdentityGaps(PDO $db,int $org,int $parent,int $bank,array $config,string $boundary):array {
        $people=[];$seen=[];
        foreach($config as $row){$key=$row['organization_id'].':'.$row['config_key'];if(isset($seen[$key]))continue;$seen[$key]=true;$v=json_decode($row['config_json'],true,512,JSON_THROW_ON_ERROR);
            if($row['config_key']==='ORG_OFFICE_HEAD_V1'&&is_int($v['employee_id']??null))$people[$v['employee_id']]=true;
            if($row['config_key']==='travel_activity_request_signatories')foreach(['sgod_chief','sds'] as $role)if(is_int($v['roles'][$role]['employee_id']??null))$people[$v['roles'][$role]['employee_id']]=true;
        }
        $scope=array_values(array_unique(array_filter([$org,$parent],static fn($id)=>$id>0)));$marks=implode(',',array_fill(0,count($scope),'?'));
        $clauses=["(entity_type='BANK' AND entity_id=? AND event_type='BANK_ACCOUNT_LABEL_RENAMED')","(entity_type='ORGANIZATION' AND entity_id IN ($marks) AND event_type='PROFILE_UPDATED')","(entity_type='SCHOOL' AND entity_id IN ($marks) AND event_type IN ('SCHOOL_ID_CHANGED','ATTACHED','CREATED'))"];
        $params=array_merge($scope,[$boundary,$bank],$scope,$scope);
        if($people){$ids=array_keys($people);$clauses[]="(entity_type='EMPLOYEE' AND entity_id IN (".implode(',',array_fill(0,count($ids),'?')).") AND event_type IN ('RENAMED','UPDATED'))";$params=array_merge($params,$ids);}
        $rows=q($db,"SELECT id,event_type,entity_type,details FROM audit_events WHERE organization_id IN ($marks) AND created_at>=? AND (".implode(' OR ',$clauses).') ORDER BY id LIMIT 501',$params)->fetchAll();
        if(count($rows)>500)return ['Relevant report identity correction history exceeds review capacity; historical report identities require reconstruction.'];
        foreach($rows as $row){
            if($row['entity_type']==='EMPLOYEE'&&$row['event_type']==='UPDATED'){
                $v=json_decode((string)$row['details'],true);$before=$v['before']??null;$after=$v['after']??null;
                // Current staff EDIT also audits payment-profile-only edits.
                // Complete identical name/position evidence cannot alter an
                // earlier report; dated assignment episodes remain preserved.
                if(is_array($before)&&is_array($after)&&isset($before['full_name'],$before['position_title'],$after['full_name'],$after['position_title'])&&$before['full_name']===$after['full_name']&&$before['position_title']===$after['position_title'])continue;
            }
            return ['An authorized report identity was corrected after the accounting cutoff; displayed office, bank or signatory identity fields were observed at capture and are historical reconstruction.'];
        }
        return [];
    }
    public static function configAllowlist():array {return ['SCHOOL_IMPLEMENTATION_CLASS','ORG_OFFICE_HEAD_V1','DV_SECTION_SIGNATORIES_V1','SCHOOL_DIVISION_MOOE_POSTING_OFFICER_V1','travel_activity_request_signatories'];}
    private function append(int $org,int $bank,string $p,array $s,string $reason):array {q($this->db,'INSERT INTO configuration_versions(organization_id,config_key,config_json,effective_from,review_note) VALUES (?,?,?,?,?)',[$org,'FR456_SNAPSHOT_'.$bank.'_'.$p,json_encode($s,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES),date('Y-m-d'),$reason]);$id=(int)$this->db->lastInsertId();q($this->db,'INSERT INTO audit_events(organization_id,actor_id,event_type,entity_type,entity_id,details) VALUES (?,?,?,?,?,?)',[$org,$this->user['id'],'FINANCE_REVIEW_SNAPSHOT_CAPTURED','FINANCE_REVIEW',$id,json_encode(['bank_id'=>$bank,'period'=>$p,'sha256'=>$s['sha256'],'provenance'=>$s['body']['basis']['provenance'],'complete'=>$s['body']['basis']['complete']],JSON_THROW_ON_ERROR)]);return ['snapshot_id'=>$id]+$s;}
    public function captureAtClose(int $org,int $bank,string $p,int $reconVersion,string $reason):array {return $this->capture(['organization_id'=>$org,'bank_account_id'=>$bank,'period'=>$p,'reason'=>$reason],$reconVersion);}
