        $historyPrefix='FR456_BANK_'.$bank.'_';$resolutionPrefix='FR456_BANK_RESOLVE_'.$bank.'_';$bankHistory=q($this->db,'SELECT id,config_key,config_json,effective_from,created_at FROM configuration_versions WHERE organization_id=? AND (LEFT(config_key,?)=? OR LEFT(config_key,?)=?) ORDER BY id LIMIT 5001',[$org,strlen($historyPrefix),$historyPrefix,strlen($resolutionPrefix),$resolutionPrefix])->fetchAll();demand(count($bankHistory)<=5000,'Reconciliation snapshot history exceeds capacity',409);
