        $latestSet=[];foreach($sets as $set)$latestSet[(int)$set['dv_id']]=(int)$set['id'];
        $eventBySet=[];foreach($allocationEvents as $e)$eventBySet[(int)$e['allocation_set_id']][]=$e;
        foreach($sets as &$set){$set['observed_state']=$set['state'];$state='RESERVED';$cash=0;foreach($eventBySet[(int)$set['id']]??[] as $e){$cash+=(int)$e['cash_delta_cents'];if($e['event_type']==='RESERVATION_REVERSED')$state='REVERSED';}if($cash>0)$state='PAID';$set['observed_active_dv_id']=$set['active_dv_id'];if(($latestSet[(int)$set['dv_id']]??0)!==(int)$set['id'])$state='SUPERSEDED';$set['state']=$state;$set['active_dv_id']=in_array($state,['REVERSED','SUPERSEDED'],true)?null:(int)$set['dv_id'];$set['as_of_cash_cents']=$cash;}unset($set);
        $latestVersions=[];foreach($versions as $v)$latestVersions[(int)$v['dv_id']]=(int)$v['id'];$reportLines=array_values(array_filter($lines,static fn($l)=>(int)$l['accounting_version_id']===($latestVersions[(int)$l['dv_id']]??0)));
