        if($typed){$out['reconTyped']=$typed;$out['reconLines']=$typed['lines'];$out['reconAdjust']=$typed['totals']['adjusted_book_cents']-$typed['book_cents'];}
        $out['organization']=$p['report_sources']['organization'];$out['appendix43']=Appendix43Register::build($out,$lines,$tax,$p['signatories']['effective_metadata']);$out['options']=['funds'=>$p['report_sources']['funds'],'banks'=>[$bank]];$out['snapshot_id']=$s['snapshot_id'];$out['snapshot_sha256']=$s['sha256'];$out['report_basis_note']='Immutable snapshot #'.$s['snapshot_id'].' / '.$basis['provenance'].' / captured '.$basis['captured_at'].'. No live source joins. Uncertified review copy.';$out['report_basis']=$out['report_basis_note'];
        foreach($basis['gaps'] as $gap){$out['warnings'][]=$gap;$out['reviewItems'][]=['code'=>'snapshot_provenance','message'=>$gap,'reports'=>['A80','S1','A35','A40','A43','A67'],'kind'=>'review'];}return $out;
    }
}
